/**
 * The live sessions behind `e2e mcp`: each one standalone attempt on one
 * target with one interactive agent step open on it, driven by a coding agent
 * through a fixed, four-tool surface. `open_session` loads the project's
 * config, or builds one around the engine package it names where the project
 * has none, and opens the attempt and the step; `tools` renders the session's
 * catalog; `call` runs one catalog tool by name inside the step;
 * `close_session` ends the step, saves a recording still running, and tears
 * the attempt down. Several sessions may be open at once, up to the server's
 * limit, so parallel agents each drive their own browser; a call names its
 * session by id, and may leave it out only while one is open. The catalog is
 * data, not registrations, so it follows the config and the target without a
 * restart and the client's tool list never changes.
 */
import { z } from 'zod';
import { loadAiSdkIfInstalled } from '../agent/ai-sdk.js';
import { openInteractiveStep } from '../agent/interactive-step.js';
import { ScreenPresenter } from '../agent/screen-update.js';
import { launchesPinnedApp } from '../config/targets.js';
import { secretHandle } from '../secrets.js';
import { classifyError, ConfigurationError, errorMessage, InfrastructureError } from '../internal/errors.js';
import { LocatorEngine } from '../locator/engine.js';
import { allocateTargetPorts } from '../run/app-ports.js';
import { selectTarget } from '../run/select-target.js';
import { SharedAppProcesses } from '../run/process-pool.js';
import { outputLayout } from '../run/output.js';
import { processSecrets, registerStaticSecrets } from '../run/secrecy.js';
import { openStandaloneAttempt } from '../run/standalone.js';
import { selectStandaloneTest, testLocation } from '../run/standalone-test.js';
import { createSessionCatalog, isGrammarVerb } from './catalog.js';
import { appLines } from './app-lines.js';
import { SESSION_BOUNDS } from './bounds.js';
import { describeRecording, SessionRecorder } from './recording.js';
import { SessionRegistry } from './sessions.js';
import { describeTestOutcome } from './test-outcome.js';
import { SessionUsage } from './usage.js';
import { actionResult, catalogLine, defineMcpTool, describeToolDetail, errorResult, invokeTool, redacting, redactResult, textResult } from './tools.js';
/** How long one session may live, whatever happens. */
const SESSION_TTL_MS = 4 * 60 * 60 * 1000;
/** A session nobody has touched for this long is closed, so no browser is left behind. */
const SESSION_IDLE_MS = 30 * 60 * 1000;
/** How long the attempt outlives its step, so a step that hit the TTL is still closed in order. */
const CLOSE_GRACE_MS = 60 * 1000;
const SESSION_INSTRUCTION = 'Interactive session: a coding agent drives the app over MCP.';
/** Where an agent reads how to write a test, said in the server's instructions and every session's opening. */
export const READ_WRITING_GUIDE = 'Before you write or edit a test, read the writing-tests guide: the resource e2e://guide/writing-tests, or npx e2e guide writing-tests in a shell.';
/** What sessions opened with `engine` claim as their config: they hold no secrets, so they share it whatever the engine. */
const ENGINE_DEFAULTS = 'engine defaults, with no config file';
/** Owns the live sessions, up to the server's limit, and the fixed MCP tools that drive them. */
export class SessionHost {
    options;
    sessions;
    /** Sessions on one app command share its process: the last one to close stops it. */
    apps = new SharedAppProcesses();
    /** Aborts every open still running once the server shuts down, so none leaves a process behind. */
    shutdown = new AbortController();
    constructor(options) {
        this.options = options;
        this.sessions = new SessionRegistry(this.maxSessions);
    }
    get isOpen() {
        return this.sessions.hasLive;
    }
    get maxSessions() {
        return this.options.maxSessions ?? SESSION_BOUNDS.default;
    }
    /** The server's tools: the same four whatever the project, the config, or the target, each redacting what it returns. */
    toolSpecs() {
        return [this.openSpec(), this.catalogSpec(), this.callSpec(), this.closeSpec()].map(redacting);
    }
    /** Logs a line for the operator and the client, redacted with every secret value the process knows. */
    log(level, message) {
        this.options.log(level, processSecrets.redact(message));
    }
    /**
     * Opens a session and returns its opening text: the summary, the catalog,
     * and the first screen. `signal` is the request's: a client that cancels
     * it, or disconnects, aborts the open and what it started.
     */
    open(options, signal) {
        const headed = options.headed ?? this.options.headed;
        const usage = new SessionUsage(this.sessions.liveCount, headed);
        return this.sessions.admit((id) => this.openSession(id, options, headed, usage, signal)).catch((cause) => {
            this.options.onSessionEnd?.(usage.openFailed(classifyError(cause).code));
            throw cause;
        });
    }
    /** Closes one session, the only one when `session` is omitted, and returns what happened; a session already closing returns that close. */
    async close(reason, session, endedBy = 'agent') {
        if (session === undefined && !this.sessions.hasLive)
            return 'No session is open.';
        return this.sessions.close(session, reason, (live) => this.teardown(live, reason, endedBy));
    }
    /** Closes every session, for a server that is shutting down; undefined when none was open. */
    async closeAll(reason) {
        this.shutdown.abort();
        const summaries = await this.sessions.closeAll(reason, (live) => this.teardown(live, reason, 'server'));
        return summaries.length === 0 ? undefined : summaries.join('\n');
    }
    async teardown(live, reason, endedBy) {
        if (live.idleTimer !== undefined)
            clearTimeout(live.idleTimer);
        const { value, cleanupErrors } = await this.closeAttempt(live.attempt, live.abort, async () => {
            await live.step.end({ status: 'passed', summary: `session closed: ${reason}` });
            const outcome = await live.step.done;
            // The recorder runs this after a start or stop still in flight, even one the step's deadline abandoned.
            return { outcome, saved: await this.saveRecording(live) };
        }).finally(() => this.options.onSessionEnd?.(live.usage.closed(endedBy)));
        const lines = [`Session ${live.id} closed (${reason}); ${live.actions} tool calls ran.`];
        if (value.saved !== undefined)
            lines.push(value.saved);
        if (value.outcome.error !== undefined)
            lines.push(`The session step ended with: ${errorMessage(value.outcome.error)}`);
        for (const error of cleanupErrors) {
            // The teardown a test left (`afterEach`, `afterAll`) says where it failed.
            const hook = error.phase === 'afterEach' || error.phase === 'afterAll' ? ` (${error.phase})` : '';
            lines.push(`Cleanup${hook}: ${error.code}: ${error.message}`);
        }
        // Redacted here, not only at the tool boundary: closeAll writes it to stderr.
        return processSecrets.redact(lines.join('\n'));
    }
    /**
     * Runs `settle` (ending the step, saving a recording), then closes the
     * attempt and cancels whatever still runs in it, whether or not `settle`
     * failed: an engine or app process left behind would block the next session.
     */
    async closeAttempt(attempt, abort, settle) {
        const settled = await settle().then((value) => ({ value }), (cause) => ({ cause }));
        const cleanupErrors = attempt === undefined ? [] : await attempt.close();
        abort.abort();
        if ('cause' in settled)
            throw settled.cause;
        return { value: settled.value, cleanupErrors };
    }
    /** The session's catalog, or one tool's full contract. */
    catalog(session, tool) {
        const live = this.sessions.resolve(session);
        if (tool === undefined) {
            return [`Session ${live.id} on target "${live.target.name}": ${Object.keys(live.catalog.tools).length} tools. Run one with call {tool, args}; tools {tool} shows a tool's arguments.`, ...this.catalogLines(live)].join('\n');
        }
        const found = live.catalog.tools[tool];
        if (found === undefined)
            throw this.unknownTool(live, tool);
        return describeToolDetail(tool, found, live.catalog.readOnly.has(tool));
    }
    /** Runs one catalog tool inside the live session's step; what comes back, a result or a failure, passes the attempt's secret ledger. */
    call(session, name, args, extra) {
        const live = this.sessions.resolve(session);
        const tool = live.catalog.tools[name];
        live.usage.called(name, live.catalog.project.has(name));
        if (tool === undefined) {
            const error = this.unknownTool(live, name);
            live.usage.failed(error.code);
            throw error;
        }
        const redact = live.attempt.agentRuntime.redact;
        return this.run(live, () => invokeTool(name, tool, args, extra)).then((result) => {
            if (!isGrammarVerb(name)) {
                // A grammar action's failure was counted with its code as it happened; a project tool's result carries none.
                if (result.isError === true)
                    live.usage.failed(undefined);
                return redactResult(result, redact);
            }
            return redactResult(actionResult(name, result), redact);
        }, (cause) => {
            live.usage.failed(classifyError(cause).code);
            return redactResult(errorResult(cause), redact);
        });
    }
    async openSession(id, options, headed, usage, request) {
        // The catalog renders synchronously, so the optional SDK is loaded once
        // here when installed. Without it the catalog reads the tools' Standard
        // Schemas, and only a model-backed call needs the package.
        await loadAiSdkIfInstalled();
        // The config is claimed before it evaluates: its top-level code resolves
        // secrets against the registry an open session installed, which only
        // knows that session's config.
        const source = this.configSource(options);
        this.sessions.claimConfig(id, 'file' in source ? `config ${source.file}` : ENGINE_DEFAULTS);
        const withhold = this.options.withholdOutput ?? ((load) => load());
        // The session's own module graph: a test it runs sees every project file as it is now.
        const graph = `mcp-${id}`;
        const loaded = await withhold(async () => {
            const fresh = 'file' in source ? await this.options.loadConfig(source.file, graph) : await this.options.loadEngineConfig(source.engine);
            // Known to the process before anything can fail with one, so an open
            // failure and what the config printed while it loaded are redacted
            // like any other text; a session registers them only once its engine
            // has launched.
            registerStaticSecrets(fresh.allSecrets);
            return fresh;
        });
        // A session is its own run: a URL declared with port 0 gets a port here,
        // for the opened target alone, so another target's URL cannot fail the open.
        // An engine session has one target, whatever `--target` names in a config.
        const named = 'file' in source ? (options.target ?? this.options.defaultTarget) : undefined;
        const { config, target } = await allocateTargetPorts(loaded, selectTarget(loaded, named, 'pass target to open_session, or start e2e mcp --target <name>'));
        usage.resolved(target.platform, target.engine);
        this.sessions.claimEngine(id, target.name, target.engine);
        // Selected before anything boots: a name that selects no test, or several, costs no engine.
        const test = options.test === undefined ? undefined : await selectStandaloneTest(config, target, options.test, graph);
        const ttlMs = this.options.ttlMs ?? SESSION_TTL_MS;
        const abort = new AbortController();
        // Until the session is live, the request and the server's shutdown can abort the open.
        const opening = AbortSignal.any([this.shutdown.signal, ...(request === undefined ? [] : [request])]);
        const cancel = () => abort.abort();
        if (opening.aborted)
            cancel();
        else
            opening.addEventListener('abort', cancel, { once: true });
        let attempt;
        let step;
        try {
            attempt = await openStandaloneAttempt({
                // A session records video only between start_recording and
                // stop_recording: the configured video mode is for runs, and would
                // record everything.
                config,
                target: { ...target, video: { mode: 'off', source: 'default' } },
                headed,
                env: this.options.env,
                signal: abort.signal,
                timeoutMs: ttlMs + CLOSE_GRACE_MS,
                processes: this.apps,
                notice: (scope, message) => this.log('info', `${scope}: ${message}`),
                ...(test === undefined ? {} : { test, agent: test.pair.agent }),
            });
            // A device has no URL for the first screen to navigate to, so its
            // pinned app launches here, as a test's `app.open()` launches it, or
            // the first observation finds no app open. A test opens the app itself.
            if (test === undefined && launchesPinnedApp(target))
                await attempt.fixtures.app.open();
            // The test runs before the step opens, so its steps are its own, and
            // the session takes over wherever it stopped.
            const ran = await attempt.test?.run();
            // The coding agent is the brain: the step is driven from here, and the
            // configured model stays out of the way.
            const params = this.secretParams(config);
            step = await openInteractiveStep(attempt.agentRuntime, {
                instruction: SESSION_INSTRUCTION,
                ...(params === undefined ? {} : { params }),
                timeout: ttlMs,
            });
            const screen = new ScreenPresenter();
            const recorder = this.recorder(id, config, attempt);
            const catalog = createSessionCatalog({
                context: step.context,
                screen,
                session: attempt.session,
                tools: config.agent.tools,
                redaction: { redact: attempt.agentRuntime.redact, redactCut: attempt.agentRuntime.redactCut },
                projectRoot: config.projectRoot,
                attemptDir: attempt.artifactsDir,
                recorder,
                appBase: target.app.base,
                fills: {
                    credentials: [...config.credentials.values()].map((credential) => ({ name: credential.name, username: credential.username, password: credential.password.name })),
                    secrets: [...config.secrets.keys()],
                },
                testRan: test === undefined ? undefined : testLocation(test.pair.test),
                locator: new LocatorEngine({
                    session: attempt.session,
                    budget: attempt.budget,
                    runId: attempt.runId,
                    attemptId: attempt.attemptId,
                    actionTimeout: config.actionTimeout,
                    assertionTimeout: config.assertionTimeout,
                }),
                warn: (message) => this.log('warning', message),
                onActionFailed: (cause) => usage.failed(classifyError(cause).code),
                runCode: { attempt, engineFixtures: Object.keys(target.engine?.fixtures ?? {}) },
            });
            const live = {
                id,
                target,
                origin: 'file' in source
                    ? `config ${source.file}, read with the e2e mcp server's environment, not your shell's.`
                    : `no config file: one target on ${source.engine.package}, every other setting at its default. run_tests and open_session {test} need an e2e.config.ts (npx e2e init writes one).`,
                headed,
                attempt,
                step,
                screen,
                catalog,
                recorder,
                abort,
                idleTimer: undefined,
                actions: 0,
                usage,
            };
            // The code frame reads the test file as it is on disk, so the text passes the session's ledger like a tool result.
            const outcome = test === undefined || ran === undefined ? undefined : attempt.agentRuntime.redact(describeTestOutcome(test, ran, config.projectRoot));
            // The screen a test stopped on is the one to show; only a fresh session opens the app URL.
            const text = this.openingText(live, config, await this.firstScreen(live, outcome === undefined), outcome);
            // A first screen that came back despite the cancel must not become a live session nobody asked for.
            if (abort.signal.aborted)
                throw new InfrastructureError('CANCELLED', `opening session ${id} was cancelled`);
            opening.removeEventListener('abort', cancel);
            this.sessions.activate(live);
            // A step that ends on its own (the TTL, a hard stop) ends the session.
            void step.done.then((ended) => this.endOnItsOwn(live, ended.error === undefined ? 'the session step concluded' : errorMessage(ended.error), 'step'));
            this.touch(live);
            return text;
        }
        catch (cause) {
            opening.removeEventListener('abort', cancel);
            await this.closeAttempt(attempt, abort, async () => {
                await step?.end({ status: 'failed', summary: 'opening the session failed' });
            }).catch(() => undefined);
            throw cause;
        }
    }
    /**
     * The project's config file, or the engine the call names for a project
     * without one. Naming an engine excludes what only a config file gives: a
     * path to one, a target of it, a test it discovers.
     */
    configSource(options) {
        const { engine, app } = options;
        if (engine === undefined) {
            if (app !== undefined)
                throw new ConfigurationError('INVALID_ARGUMENT', 'open_session: app describes the session engine opens; pass engine with it, or leave it out');
            return { file: this.options.locateConfig(options.config) };
        }
        const needsConfig = Object.entries({ config: options.config, target: options.target, test: options.test }).find(([, value]) => value !== undefined)?.[0];
        if (needsConfig !== undefined) {
            throw new ConfigurationError('INVALID_ARGUMENT', `open_session: ${needsConfig} names part of a config file, and engine opens a session without one; pass one or the other`);
        }
        return { engine: { ...(typeof engine === 'string' ? { package: engine } : engine), ...(app === undefined ? {} : { app }) } };
    }
    /** Closes a live session that ended without a close_session: its step concluded, or it sat idle. */
    endOnItsOwn(live, why, endedBy) {
        if (!this.sessions.isLive(live.id))
            return;
        this.log('warning', `session ${live.id} ended: ${why}`);
        this.close(why, live.id, endedBy).catch((cause) => this.log('error', `closing session ${live.id} failed: ${errorMessage(cause)}`));
    }
    /** A recorder writing to `<output>/videos/<session>/`, when the engine records video. */
    recorder(id, config, attempt) {
        const { startVideo, stopVideo } = attempt.session.artifacts;
        if (startVideo === undefined || stopVideo === undefined)
            return undefined;
        return new SessionRecorder({
            startVideo,
            stopVideo,
            attemptDir: attempt.artifactsDir,
            outDir: outputLayout(config.output).videos(id),
            // Not the attempt's signal: a session that hit its TTL still saves the recording on the way out.
            operation: (timeoutMs) => ({
                signal: AbortSignal.timeout(timeoutMs),
                timeoutMs,
                runId: attempt.runId,
                attemptId: attempt.attemptId,
                origin: 'test',
            }),
            timeoutMs: config.cleanupTimeout,
        });
    }
    /**
     * Stops a recording still running when the session closes, and says where
     * it went or why it was lost. Always queued, never checked first: a start
     * still in flight is not running yet, and would record past the close.
     */
    async saveRecording(live) {
        if (live.recorder === undefined)
            return undefined;
        try {
            const recording = await live.recorder.stop();
            return recording === undefined ? undefined : describeRecording(recording);
        }
        catch (cause) {
            return `The running recording could not be saved: ${errorMessage(cause)}`;
        }
    }
    /**
     * Opens the app URL when `open` asks and the engine can navigate, then
     * observes; a device's pinned app launched before the step opened. Either
     * opening is the test's `app.open()`, the session's first test line.
     * Without `open` the screen is the one a test left, and a test that failed
     * before it opened the app left none. The test's own lines are in its
     * file, so the session's first line is the agent's first action. The
     * observation goes through the catalog's context, which keeps it for that
     * action's line.
     */
    async firstScreen(live, open) {
        if (!open) {
            try {
                return live.screen.initial(await live.step.run(() => live.catalog.context.observe()));
            }
            catch (cause) {
                return `No screen to show: ${errorMessage(cause)}`;
            }
        }
        const base = live.target.app.base?.href;
        if (base !== undefined && live.step.context.target.verbs.has('navigate')) {
            try {
                await live.step.run((context) => context.actions.navigate(base));
            }
            catch (cause) {
                return `Opening ${base} failed: ${errorMessage(cause)}\nUse navigate once the app is reachable.`;
            }
            live.catalog.lines.opened();
        }
        else if (launchesPinnedApp(live.target)) {
            live.catalog.lines.opened();
        }
        const observation = await live.step.run(() => live.catalog.context.observe());
        return live.screen.initial(observation);
    }
    /** The summary, the catalog, and the screen, after how the session's test ran when it ran one. */
    openingText(live, config, screen, outcome) {
        const engine = live.target.engine;
        const lines = [
            ...(outcome === undefined ? [] : [outcome, '']),
            `Session ${live.id} open on target "${live.target.name}" (platform ${live.target.platform}, engine ${engine === undefined ? 'none' : `${engine.name} ${engine.version}`}), ${live.headed ? 'headed' : 'headless'}; ${live.origin}`,
        ];
        lines.push(...appLines(live.target, outcome !== undefined));
        if (config.credentials.size > 0) {
            const described = [...config.credentials.values()].map((credential) => `"${credential.name}" (username ${JSON.stringify(credential.username)}, password secret "${credential.password.name}")`);
            lines.push(`Credentials: ${described.join(', ')}. Type the username with type; fill the password with type_secret and its password secret's name.`);
        }
        if (config.secrets.size > 0) {
            lines.push(`Secrets: ${[...config.secrets.keys()].map((name) => `"${name}"`).join(', ')}. Fill one into any input with type_secret and its name; you never see the value.`);
        }
        lines.push(`Pass session "${live.id}" to every tools, call, and close_session; with several sessions open, a call without it fails.`);
        lines.push(`Tools (run one with call {tool, args}; tools {tool} shows a tool's arguments):`, ...this.catalogLines(live));
        lines.push('Node ids ("n42") are valid only for the newest observation; every action reports what changed on screen and the test line that repeats it (test_lines returns them all), and observe shows the whole screen. Call close_session when you are done.', READ_WRITING_GUIDE);
        return `${lines.join('\n')}\n\n${screen}`;
    }
    catalogLines(live) {
        return Object.entries(live.catalog.tools).map(([name, tool]) => catalogLine(name, tool, live.catalog.readOnly.has(name)));
    }
    /** Every configured secret, passwords included, as a step secret, so `type_secret` can fill it. */
    secretParams(config) {
        if (config.allSecrets.size === 0)
            return undefined;
        return Object.fromEntries([...config.allSecrets.values()].map((secret) => [secret.name, secretHandle(secret)]));
    }
    unknownTool(live, name) {
        if (isGrammarVerb(name)) {
            return new ConfigurationError('UNSUPPORTED_CAPABILITY', `tool "${name}" is not available in this session: the engine of target "${live.target.name}" declares no such action; tools lists what it can do`);
        }
        return new ConfigurationError('UNKNOWN_TOOL', `tool "${name}" is not available in this session; tools: ${Object.keys(live.catalog.tools).join(', ')}`);
    }
    touch(live) {
        if (live.idleTimer !== undefined)
            clearTimeout(live.idleTimer);
        const idleMs = this.options.idleMs ?? SESSION_IDLE_MS;
        live.idleTimer = setTimeout(() => this.endOnItsOwn(live, `idle for ${Math.round(idleMs / 60_000)} minutes`, 'idle'), idleMs);
        live.idleTimer.unref();
    }
    /** Runs one tool body inside the live session's step. */
    run(live, body) {
        this.touch(live);
        live.actions += 1;
        return live.step.run(body);
    }
    // --- the fixed tools ---
    openSpec() {
        return defineMcpTool({
            name: 'open_session',
            description: 'Open a live session on one target of an e2e project: loads the config, starts the app command the target declares (if any), boots the engine (a browser, a simulator), opens the app (its URL, or the pinned app on a device), and returns the session id, the catalog of tools it can run, and the first observation. Where the project has no e2e config file, pass engine to open a session on that engine: {engine: "@e2e-dev/web", app: {url: "http://localhost:3000"}}. With test, it runs that one test first and stops on the screen where the test passed or failed, with the failure and its line ahead of the catalog. Several sessions can be open at once, one per agent, each with its own engine: pass the returned session id to every later call. Then act with call and look with call {tool: "observe"}.',
            inputSchema: z.object({
                target: z.string().min(1).optional().describe('Target name from the config; required when the config declares several'),
                config: z.string().min(1).optional().describe("Path to an e2e config file, absolute or relative to the server's working directory; default: the nearest e2e.config.ts, .mts, .js, or .mjs"),
                headed: z
                    .boolean()
                    .optional()
                    .describe('Show the browser or simulator, when the engine supports it; pass true when the user wants to watch. Default: headless, unless the server was started with --headed'),
                test: z
                    .string()
                    .min(1)
                    .optional()
                    .describe('One test to run in the session first, named the way npx e2e run takes it: tests/checkout.e2e.ts:12, where 12 is the line its test( call is on (not a failing line inside it), or a file or name that selects one test. The session then stays on the screen where the test stopped; afterEach hooks and fixture teardown run at close_session. To rerun after editing the test, close_session and open_session with test again'),
                engine: z
                    .union([
                    z.string().min(1),
                    z
                        .object({
                        package: z.string().min(1).describe('The package, with a subpath when the factory lives on one: @e2e-dev/mobile, @e2e-dev/testmu/web'),
                        export: z.string().min(1).optional().describe('The export to call; default: the default export'),
                        options: z
                            .record(z.string(), z.unknown())
                            .optional()
                            .describe('What the factory is called with, as in an e2e.config.ts. A value of this same {package, export?, options?} shape is called first and replaced by its result'),
                    })
                        .strict(),
                ])
                    .optional()
                    .describe('Only where the project has no config file: the engine to open a session on, as a config would build it. A package name calls its default export with no options: "@e2e-dev/web". An object passes options, and an option can be another factory call, which is how an engine gets a device or browser provider: {package: "@e2e-dev/mobile", options: {platform: "ios"}}, or {package: "@e2e-dev/mobile", options: {platform: "ios", device: {package: "@e2e-dev/limrun", export: "limrun", options: {region: "eu"}}}} for mobile({platform: "ios", device: limrun({region: "eu"})}). A package not installed fails with the command that installs it. Excludes target, config, and test'),
                app: z
                    .object({
                    url: z.string().min(1).optional().describe('The URL the session opens, and the base of relative navigation'),
                    bundleId: z.string().min(1).optional().describe('An installed app a device launches: its bundle id, package, or display name'),
                    appPath: z.string().min(1).optional().describe("A build a device installs and launches: an .app, .ipa, or .apk, relative to the server's working directory"),
                })
                    .strict()
                    .optional()
                    .describe('With engine: the app under test, as a target declares it in an e2e.config.ts. @e2e-dev/web needs url; @e2e-dev/mobile needs bundleId or appPath'),
            }).strict(),
            readOnly: false,
            call: async (args, extra) => textResult(await this.open(args, extra.signal)),
        });
    }
    catalogSpec() {
        return defineMcpTool({
            name: 'tools',
            description: "List the tools a session can run through call: observe, the grammar its engine honors (one tool per action the engine declares, type_secret when a secret is configured, and screenshot and the point tools), locate, run_code (test statements run on the live app), test_lines (the test line each action printed and the statements run_code passed, as a draft test body), start_recording and stop_recording when the engine records video, and the project's own tools. With tool, shows that tool's full description and the JSON Schema of its arguments.",
            inputSchema: z.object({
                tool: z.string().min(1).optional().describe('A catalog tool name, for its full contract'),
                session: z.string().min(1).optional().describe('Session id from open_session; may be omitted only while one session is open'),
            }).strict(),
            readOnly: true,
            call: async (args) => textResult(this.catalog(args.session, args.tool)),
        });
    }
    callSpec() {
        return defineMcpTool({
            name: 'call',
            description: "Run one tool of a session by name, with its arguments as an object: call {tool: \"tap\", args: {target: \"n42\"}, session: \"<id>\"}. The session's catalog (from open_session or tools) names the tools and their arguments. Actions report what changed on screen and the test line that repeats them; node ids are valid only for the newest observation.",
            inputSchema: z.object({
                tool: z.string().min(1).describe('A catalog tool name, e.g. "observe", "tap", "locate", "screenshot"'),
                args: z.record(z.string(), z.unknown()).optional().describe("The tool's arguments; omit for a tool without any"),
                session: z.string().min(1).optional().describe('Session id from open_session; may be omitted only while one session is open'),
            }).strict(),
            readOnly: false,
            call: (args, extra) => this.call(args.session, args.tool, args.args ?? {}, extra),
        });
    }
    closeSpec() {
        return defineMcpTool({
            name: 'close_session',
            description: 'Close a live session: save a recording still running, end the attempt, dispose the engine, and stop the app processes the session started.',
            inputSchema: z.object({
                session: z.string().min(1).optional().describe('Session id from open_session; may be omitted only while one session is open'),
            }).strict(),
            readOnly: false,
            call: async (args) => textResult(await this.close('closed by the agent', args.session)),
        });
    }
}
